// Payload: 'on' | 'off' | 'dimmed'
// Validates and applies display state change
// Updates panel state in flow context
// Publishes display/state back to confirm

const state = flow.get('panel_kitchen') || {}
const newDisplayState = msg.payload

if (!['on', 'off', 'dimmed'].includes(newDisplayState)) {
    node.warn('Invalid display state: ' + newDisplayState)
    return null
}

state.display_state = newDisplayState
flow.set('panel_kitchen', state)

// If turning off, also cancel blanking suppression
if (newDisplayState === 'off') {
    state.blanking_suppressed = false
    state.blanking_suppressed_until = null
}

msg.topic = 'dashboard/panels/kitchen/display/state'
msg.payload = newDisplayState
return msg

// Payload: view name string e.g. 'main_menu', 'music', 'climate', etc.
// Valid views: main_menu, morning, music, climate, cameras, grafana, homeassistant
// Adult-only views: grafana, homeassistant
// Kids are redirected from adult-only views to main_menu

const VALID_VIEWS = ['main_menu', 'morning', 'music', 'climate', 'cameras', 'grafana', 'homeassistant']
const ADULT_ONLY = ['grafana', 'homeassistant']

const state = flow.get('panel_kitchen') || {}
const requestedView = msg.payload

if (!VALID_VIEWS.includes(requestedView)) {
    node.warn('Invalid view: ' + requestedView)
    return null
}

if (ADULT_ONLY.includes(requestedView) && state.mode !== 'adult') {
    node.warn('Adult-only view blocked in kids mode')
    return null
}

state.previous_view = state.current_view || 'main_menu'
state.current_view = requestedView
flow.set('panel_kitchen', state)

msg.topic = 'dashboard/panels/kitchen/view/state'
msg.payload = requestedView
return msg

// Payload: { pin: '1234' }
// Compares against configured PIN (from global config or env)
// SECURITY NOTE: PIN should be stored in Node-RED environment variables, not hardcoded
// Set NR_KITCHEN_PIN environment variable in settings.js or docker-compose

const CONFIGURED_PIN = env.get('NR_KITCHEN_PIN') || '1234'
const SESSION_SECONDS = 300

const { pin } = msg.payload
const state = flow.get('panel_kitchen') || {}

if (pin === CONFIGURED_PIN) {
    const expiresAt = new Date(Date.now() + SESSION_SECONDS * 1000).toISOString()
    state.mode = 'adult'
    state.adult_session_expires_at = expiresAt
    flow.set('panel_kitchen', state)

    // Schedule auto-expire
    const timer = flow.get('adult_timer')
    if (timer) clearTimeout(timer)
    const newTimer = setTimeout(() => {
        const s = flow.get('panel_kitchen') || {}
        s.mode = 'kids'
        s.adult_session_expires_at = null
        flow.set('panel_kitchen', s)
        node.send([null, { topic: 'dashboard/panels/kitchen/mode/state', payload: JSON.stringify({ mode: 'kids' }) }])
    }, SESSION_SECONDS * 1000)
    flow.set('adult_timer', newTimer)

    return [{ topic: 'dashboard/panels/kitchen/pin/result', payload: JSON.stringify({ success: true, mode: 'adult', expires_at: expiresAt }) }, null]
} else {
    return [{ topic: 'dashboard/panels/kitchen/pin/result', payload: JSON.stringify({ success: false, error: 'invalid_pin' }) }, null]
}

info:
Controls display blanking suppression.
Actions: extend, reduce, cancel
Publishes blanking/inhibit/state with { active: bool, until: ISO string }

func:
// Payload: { action: 'extend'|'reduce'|'cancel', seconds: number }
// extend: adds seconds to current until (or starts fresh from now)
// reduce: subtracts seconds from until (min = now)
// cancel: clears suppression immediately

const { action, seconds } = msg.payload
const state = flow.get('panel_kitchen') || {}
const now = Date.now()
const STEP = seconds || 1800

let currentUntil = state.blanking_suppressed_until
    ? new Date(state.blanking_suppressed_until).getTime()
    : now

if (action === 'cancel') {
    state.blanking_suppressed = false
    state.blanking_suppressed_until = null
} else if (action === 'extend') {
    const base = Math.max(currentUntil, now)
    const newUntil = base + STEP * 1000
    state.blanking_suppressed = true
    state.blanking_suppressed_until = new Date(newUntil).toISOString()
} else if (action === 'reduce') {
    const newUntil = Math.max(now, currentUntil - STEP * 1000)
    if (newUntil <= now + 5000) {
        state.blanking_suppressed = false
        state.blanking_suppressed_until = null
    } else {
        state.blanking_suppressed_until = new Date(newUntil).toISOString()
    }
}

flow.set('panel_kitchen', state)

msg.topic = 'dashboard/panels/kitchen/blanking/inhibit/state'
msg.payload = JSON.stringify({
    active: state.blanking_suppressed,
    until: state.blanking_suppressed_until
})
return msg

// Payload: { camera_id, camera_url, camera_name, duration_seconds }
const { camera_id, camera_url, camera_name, duration_seconds } = msg.payload
const state = flow.get('panel_kitchen') || {}
const duration = duration_seconds || 120
const expiresAt = new Date(Date.now() + duration * 1000).toISOString()

const override = {
    type: 'camera',
    camera_id,
    camera_url,
    camera_name,
    expires_at: expiresAt,
    started_at: new Date().toISOString()
}

state.active_override = override
flow.set('panel_kitchen', state)

// Auto-restore after duration
const timer = flow.get('camera_timer')
if (timer) clearTimeout(timer)
const newTimer = setTimeout(() => {
    const s = flow.get('panel_kitchen') || {}
    s.active_override = null
    flow.set('panel_kitchen', s)
    node.send({ topic: 'dashboard/panels/kitchen/override/state', payload: JSON.stringify(null) })
}, duration * 1000)
flow.set('camera_timer', newTimer)

msg.topic = 'dashboard/panels/kitchen/override/state'
msg.payload = JSON.stringify(override)
return msg

// Cancel active override and restore previous state
const state = flow.get('panel_kitchen') || {}
state.active_override = null
flow.set('panel_kitchen', state)

const timer = flow.get('camera_timer')
if (timer) clearTimeout(timer)

msg.topic = 'dashboard/panels/kitchen/override/state'
msg.payload = JSON.stringify(null)
return msg

info:
Receives dashboard/scenes/trigger with { scene_id }
Routes to Home Assistant and/or Sonos based on global config
Publishes confirmation back

func:
// Payload: { scene_id: 'yoga' | 'kinderparty' | etc. }
// Looks up scene config from global config
// Sends HA service call via HTTP request node (output 1)
// Sends Sonos command if playlist defined (output 2)

const SCENE_CONFIG = {
    yoga:        { ha_scene: 'scene.yoga',        sonos_playlist: null },
    kinderparty: { ha_scene: 'scene.kinderparty', sonos_playlist: 'kids_songs' },
    abendessen:  { ha_scene: 'scene.abendessen',  sonos_playlist: null },
    nachtmodus:  { ha_scene: 'scene.nachtmodus',  sonos_playlist: null },
}

const { scene_id } = msg.payload
const scene = SCENE_CONFIG[scene_id]

if (!scene) {
    node.warn('Unknown scene: ' + scene_id)
    return [null, null]
}

const haMsg = {
    method: 'POST',
    url: (env.get('HA_URL') || 'http://homeassistant.local:8123') + '/api/services/scene/turn_on',
    headers: {
        'Authorization': 'Bearer ' + (env.get('HA_TOKEN') || ''),
        'Content-Type': 'application/json'
    },
    payload: JSON.stringify({ entity_id: scene.ha_scene })
}

if (scene.sonos_playlist) {
    const sonosMsg = {
        topic: 'dashboard/sonos/command',
        payload: JSON.stringify({ action: 'play_playlist', playlist_id: scene.sonos_playlist })
    }
    return [haMsg, sonosMsg]
}

return [haMsg, null]

