Receives dashboard/sonos/command with:
  { action: 'play_playlist', playlist_id, volume }
  { action: 'stop' }
  { action: 'volume_delta', delta }
Sends HTTP requests to Sonos HTTP API (sonos-http-api or node-sonos-http-api)

func:
// Translates playlist_id to Sonos URI/favorite
// Calls node-sonos-http-api: GET http://sonos-api:5005/{room}/favorite/{name}
const PLAYLISTS = {
    kids_songs:   'Kinderlieder',
    radio_energy: 'Energy',
    classical:    'Klassik',
}
const room = env.get('SONOS_ROOM') || 'Küche'
const favName = PLAYLISTS[msg.payload.playlist_id] || msg.payload.playlist_id
const sonosApiUrl = env.get('SONOS_API_URL') || 'http://localhost:5005'

const volume = msg.payload.volume
msg.method = 'GET'
msg.url = `${sonosApiUrl}/${encodeURIComponent(room)}/favorite/${encodeURIComponent(favName)}`
if (volume != null) {
    return [msg, { method: 'GET', url: `${sonosApiUrl}/${encodeURIComponent(room)}/volume/${volume}` }]
}
return [msg, null]

// Only process messages with occupancy=true
// Map topic to panel_id using sensor config
const SENSOR_MAP = {
    'zigbee2mqtt/kitchen_motion':  { panel_id: 'kitchen', outdoor: false },
    'zigbee2mqtt/garden_motion':   { panel_id: 'kitchen', outdoor: true },
}

const sensor = SENSOR_MAP[msg.topic]
if (!sensor) return null
if (!msg.payload || !msg.payload.occupancy) return null

msg.sensor = sensor
return msg

// Called when occupancy=true detected
// Checks wake_on_motion / wake_on_outdoor_motion setting
// If display is off: sends display/set on

const state = flow.get('panel_kitchen') || {}
const { panel_id, outdoor } = msg.sensor

if (panel_id !== 'kitchen') return null

const shouldWake = outdoor ? state.wake_on_outdoor_motion : state.wake_on_motion
if (!shouldWake) return null
if (state.display_state !== 'off') return null

msg.topic = `dashboard/panels/${panel_id}/display/set`
msg.payload = 'on'
return msg
